ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
CREATE OR REPLACE FUNCTION public.handle_new_user_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,email) VALUES(new.id,coalesce(new.email,'')) ON CONFLICT DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'user') ON CONFLICT DO NOTHING; RETURN new; END $$;
CREATE TRIGGER on_auth_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user_role();
GRANT SELECT ON public.profiles,public.deposits,public.surprises,public.user_roles TO authenticated;
GRANT ALL ON public.profiles,public.deposits,public.surprises,public.templates,public.settings,public.user_roles TO service_role;
GRANT SELECT ON public.templates,public.settings TO anon,authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.deposits,public.surprises FROM authenticated;
CREATE OR REPLACE FUNCTION public.request_deposit(_amount integer,_note text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND NOT banned AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Account unavailable'; END IF; IF _amount<=0 OR length(_note)>500 THEN RAISE EXCEPTION 'Invalid request'; END IF; INSERT INTO deposits(user_id,amount_inr,note,status) VALUES(auth.uid(),_amount,_note,'pending') RETURNING id INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.purchase_template(_template uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE price integer; balance bigint; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; PERFORM 1 FROM profiles WHERE id=auth.uid() AND NOT banned AND deleted_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Account unavailable'; END IF; SELECT price_inr INTO price FROM templates WHERE id=_template AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Template unavailable'; END IF; SELECT coalesce((SELECT sum(amount_inr) FROM deposits WHERE user_id=auth.uid() AND status='approved'),0)-coalesce((SELECT sum(amount_inr) FROM surprises WHERE user_id=auth.uid() AND status IN('paid','delivered')),0) INTO balance; IF balance<price THEN RAISE EXCEPTION 'Insufficient approved credit'; END IF; INSERT INTO surprises(user_id,template_id,recipient_name,sender_name,amount_inr,status) VALUES(auth.uid(),_template,'Someone special','With love',price,'paid') RETURNING id INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.save_surprise(_id uuid,_recipient text,_sender text,_headline text,_message text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND NOT banned AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Account unavailable'; END IF; IF length(_recipient) NOT BETWEEN 1 AND 100 OR length(_sender) NOT BETWEEN 1 AND 100 OR length(_headline)>200 OR length(_message)>5000 THEN RAISE EXCEPTION 'Invalid content'; END IF; UPDATE surprises SET recipient_name=_recipient,sender_name=_sender,headline=_headline,message=_message WHERE id=_id AND user_id=auth.uid() AND status IN('paid','delivered'); IF NOT FOUND THEN RAISE EXCEPTION 'Approved access required'; END IF; END $$;
REVOKE ALL ON FUNCTION public.request_deposit(integer,text),public.purchase_template(uuid),public.save_surprise(uuid,text,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.request_deposit(integer,text),public.purchase_template(uuid),public.save_surprise(uuid,text,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_surprise(_code text) RETURNS TABLE(recipient_name text,sender_name text,headline text,message text,photos text[],status text,style text,category text,cover_image text,title text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.recipient_name,s.sender_name,s.headline,s.message,s.photos,s.status,t.style,t.category,t.cover_image,t.title FROM surprises s JOIN templates t ON t.id=s.template_id JOIN profiles p ON p.id=s.user_id WHERE s.code=_code AND s.status IN('paid','delivered') AND NOT p.banned AND p.deleted_at IS NULL $$;